"use strict";(self.webpackChunkdammy=self.webpackChunkdammy||[]).push([[152],{6573:(n,s,a)=>{a.r(s),a.d(s,{data:()=>e});const e={key:"v-438a63ad",path:"/ja/usage/",title:"使い方",lang:"ja-JP",frontmatter:{},excerpt:"",headers:[{level:2,title:"基本的な使い方",slug:"基本的な使い方",children:[]},{level:2,title:"ファイルの生成",slug:"ファイルの生成",children:[{level:3,title:"ファイル数の指定",slug:"ファイル数の指定",children:[]},{level:3,title:"拡張子の指定",slug:"拡張子の指定",children:[]}]},{level:2,title:"画像ファイルの生成",slug:"画像ファイルの生成",children:[{level:3,title:"画像サイズの指定",slug:"画像サイズの指定",children:[]}]},{level:2,title:"ファイル名オプション",slug:"ファイル名オプション",children:[{level:3,title:"記号なし",slug:"記号なし",children:[]},{level:3,title:"空白入り",slug:"空白入り",children:[]},{level:3,title:"全角文字入り",slug:"全角文字入り",children:[]}]},{level:2,title:"ディレクトリの生成",slug:"ディレクトリの生成",children:[{level:3,title:"複数のディレクトリ",slug:"複数のディレクトリ",children:[]},{level:3,title:"中間ディレクトリにもファイルを生成",slug:"中間ディレクトリにもファイルを生成",children:[]}]},{level:2,title:"シェルのブレース展開",slug:"シェルのブレース展開",children:[]},{level:2,title:"Cold run（事前確認）",slug:"cold-run-事前確認",children:[]},{level:2,title:"オプション一覧",slug:"オプション一覧",children:[]}],filePathRelative:"ja/usage/README.md",git:{updatedTime:1779339153e3,contributors:[{name:"ontheroadjp",email:"dev@ontheroad.jp",commits:2}]}}},6511:(n,s,a)=>{a.r(s),a.d(s,{default:()=>p});const e=(0,a(6252).uE)('<h1 id="使い方" tabindex="-1"><a class="header-anchor" href="#使い方" aria-hidden="true">#</a> 使い方</h1><h2 id="基本的な使い方" tabindex="-1"><a class="header-anchor" href="#基本的な使い方" aria-hidden="true">#</a> 基本的な使い方</h2><p>引数なしで <code>dammy.sh</code> を実行すると、カレントディレクトリにダミーの <code>.txt</code> ファイルが1つ生成されます。</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh\n$ tree\n<span class="token builtin class-name">.</span>\n└── 0hi<span class="token punctuation">)</span>_mB.wf.txt\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><hr><h2 id="ファイルの生成" tabindex="-1"><a class="header-anchor" href="#ファイルの生成" aria-hidden="true">#</a> ファイルの生成</h2><h3 id="ファイル数の指定" tabindex="-1"><a class="header-anchor" href="#ファイル数の指定" aria-hidden="true">#</a> ファイル数の指定</h3><p><code>-n</code> オプションで生成するファイル数を指定します。</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh -n <span class="token number">3</span>\n$ tree\n<span class="token builtin class-name">.</span>\n├── <span class="token variable">$qxT2</span>+_&#39;uW.txt\n├── pdK:gXwu.Q.txt\n└── tl4NUT<span class="token punctuation">(</span>q7b.txt\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h3 id="拡張子の指定" tabindex="-1"><a class="header-anchor" href="#拡張子の指定" aria-hidden="true">#</a> 拡張子の指定</h3><p><code>-e</code> オプションで拡張子を指定します。デフォルトは <code>txt</code> です。</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh -n <span class="token number">3</span> -e csv\n$ tree\n<span class="token builtin class-name">.</span>\n├── <span class="token punctuation">;</span>mSu179.QE.csv\n├── JGElYbT3d<span class="token punctuation">\\</span>.csv\n└── tyP+<span class="token punctuation">\\</span>woXGQ.csv\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><hr><h2 id="画像ファイルの生成" tabindex="-1"><a class="header-anchor" href="#画像ファイルの生成" aria-hidden="true">#</a> 画像ファイルの生成</h2><p><code>-e</code> に画像フォーマットを指定すると、空ファイルの代わりに ImageMagick を使って<strong>実際の画像ファイル</strong>を生成します。グレー一色の背景に画像サイズが中央に表記されたシンプルな画像で、Web 開発のモックアップやフロントエンドのテストにすぐ使えます。</p><p>対応フォーマット: <code>jpg</code> <code>jpeg</code> <code>png</code> <code>gif</code> <code>bmp</code> <code>tiff</code> <code>webp</code></p><p>ファイル名は画像サイズになります（例: <code>100x100.jpg</code>）。複数生成時は連番が付きます。</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh -n <span class="token number">3</span> -e jpg\n$ tree\n<span class="token builtin class-name">.</span>\n├── 100x100_1.jpg\n├── 100x100_2.jpg\n└── 100x100_3.jpg\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h3 id="画像サイズの指定" tabindex="-1"><a class="header-anchor" href="#画像サイズの指定" aria-hidden="true">#</a> 画像サイズの指定</h3><p><code>-s</code> オプションで画像サイズを <code>幅x高さ</code> の形式で指定します。デフォルトは <code>100x100</code> です。</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh -n <span class="token number">3</span> -e png -s 320x240\n$ tree\n<span class="token builtin class-name">.</span>\n├── 320x240_1.png\n├── 320x240_2.png\n└── 320x240_3.png\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><div class="custom-container tip"><p class="custom-container-title">TIP</p><p>画像生成には ImageMagick のインストールが必要です。未インストールの場合、dammy はインストール方法を案内してエラー終了します。</p></div><hr><h2 id="ファイル名オプション" tabindex="-1"><a class="header-anchor" href="#ファイル名オプション" aria-hidden="true">#</a> ファイル名オプション</h2><h3 id="記号なし" tabindex="-1"><a class="header-anchor" href="#記号なし" aria-hidden="true">#</a> 記号なし</h3><p><code>--no-symbol</code> を付けると、英数字のみのファイル名でファイルを生成します。</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh -n <span class="token number">3</span> --no-symbol\n$ tree\n<span class="token builtin class-name">.</span>\n├── Q5aocxH9uI.txt\n├── TfxZIic3Rg.txt\n└── ucmiz657Ae.txt\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h3 id="空白入り" tabindex="-1"><a class="header-anchor" href="#空白入り" aria-hidden="true">#</a> 空白入り</h3><p><code>--with-whitespace</code> を付けると、ファイル名にスペースを含めます。スペース入りパスの処理をテストしたいときに便利です。</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh -n <span class="token number">3</span> --with-whitespace\n$ tree\n<span class="token builtin class-name">.</span>\n├── J L $ A <span class="token punctuation">(</span> .txt\n├── T w N V c .txt\n└── V n <span class="token number">0</span> <span class="token punctuation">)</span> Z .txt\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h3 id="全角文字入り" tabindex="-1"><a class="header-anchor" href="#全角文字入り" aria-hidden="true">#</a> 全角文字入り</h3><p><code>--zenkaku</code> を付けると、ファイル名に全角文字（日本語）を含めます。マルチバイトファイル名の処理をテストしたいときに便利です。</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh -n <span class="token number">3</span> --zenkaku\n$ tree\n<span class="token builtin class-name">.</span>\n├── 3aしにmう.txt\n├── Xたれ9かi.txt\n└── ゆBwはZ1.txt\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><hr><h2 id="ディレクトリの生成" tabindex="-1"><a class="header-anchor" href="#ディレクトリの生成" aria-hidden="true">#</a> ディレクトリの生成</h2><p>引数にパスを渡すと、ディレクトリを作成してその中にファイルを生成します。中間ディレクトリが存在しない場合は自動で作成されます。</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh hoge/foo/bar -n <span class="token number">2</span>\n$ tree\n<span class="token builtin class-name">.</span>\n└── hoge\n    └── foo\n        └── bar\n            ├── :w9a@DmC~N.txt\n            └── Ab3Kp<span class="token operator">!</span>mQvX.txt\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h3 id="複数のディレクトリ" tabindex="-1"><a class="header-anchor" href="#複数のディレクトリ" aria-hidden="true">#</a> 複数のディレクトリ</h3><p>複数のパスを渡すと、それぞれのディレクトリにファイルを生成します。</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh hoge foo bar\n$ tree\n<span class="token builtin class-name">.</span>\n├── bar\n│   └── J<span class="token punctuation">(</span>q<span class="token operator">=</span>E.@Ma0.txt\n├── foo\n│   └── x<span class="token operator">&amp;</span>bY,2s<span class="token punctuation">)</span>qg.txt\n└── hoge\n    └── 9BcTRkOgLw.txt\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><h3 id="中間ディレクトリにもファイルを生成" tabindex="-1"><a class="header-anchor" href="#中間ディレクトリにもファイルを生成" aria-hidden="true">#</a> 中間ディレクトリにもファイルを生成</h3><p><code>--each</code> を付けると、最深のディレクトリだけでなく、パス上の全ディレクトリにファイルを生成します。</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh hoge/foo/bar --each\n$ tree\n<span class="token builtin class-name">.</span>\n└── hoge\n    ├── <span class="token operator">&amp;</span>dGzWh<span class="token operator">!</span>F2f.txt\n    ├── foo\n    │   ├── Pq7mNzKsYo.txt\n    │   └── bar\n    │       └── %<span class="token punctuation">\\</span>&#39;fRw2z,h.txt\n    └── yLv*lTz<span class="token punctuation">\\</span>BG.txt\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><hr><h2 id="シェルのブレース展開" tabindex="-1"><a class="header-anchor" href="#シェルのブレース展開" aria-hidden="true">#</a> シェルのブレース展開</h2><p>シェルのブレース展開と組み合わせることができます。</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh hoge/<span class="token punctuation">{</span>foo,bar<span class="token punctuation">}</span>/piyo -n <span class="token number">2</span>\n$ tree\n<span class="token builtin class-name">.</span>\n└── hoge\n    ├── bar\n    │   └── piyo\n    │       ├── ey<span class="token punctuation">\\</span>%lAFx2V.txt\n    │       └── 9k~MYXwoH<span class="token operator">!</span>.txt\n    └── foo\n        └── piyo\n            ├── Kd4pRmTzWq.txt\n            └── Vu8nXjBsLe.txt\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><hr><h2 id="cold-run-事前確認" tabindex="-1"><a class="header-anchor" href="#cold-run-事前確認" aria-hidden="true">#</a> Cold run（事前確認）</h2><p><code>--cold-run</code> を付けると、実際にはファイルを生成せず、生成される予定のディレクトリツリーだけを表示します。実行前の確認に使えます。</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh hoge/<span class="token punctuation">{</span>foo,bar<span class="token punctuation">}</span>/piyo --each -n <span class="token number">3</span> --cold-run\n<span class="token builtin class-name">.</span>\n└── hoge\n    ├── +_60SaTUoh.txt\n    ├── COrDP*WZ2X.txt\n    ├── S:0myGYPX<span class="token punctuation">(</span>.txt\n    ├── bar\n    │   ├── <span class="token number">9</span><span class="token punctuation">\\</span><span class="token punctuation">\\</span><span class="token operator">=</span>o7y5<span class="token punctuation">)</span>:e.txt\n    │   ├── CJso1@z<span class="token punctuation">)</span>ZD.txt\n    │   ├── Lg7<span class="token punctuation">)</span>ruOtbH.txt\n    │   └── piyo\n    │       ├── <span class="token operator">&amp;</span>:u-BmLSa3.txt\n    │       ├── _j,eoIl1nZ.txt\n    │       └── gd,5xhU<span class="token punctuation">(</span><span class="token operator">!</span>o.txt\n    ├── d6g.pTULy9.txt\n    ├── foo\n    │   ├── 0A<span class="token punctuation">)</span>T<span class="token operator">=</span>qK@Uh.txt\n    │   ├── R8*.40<span class="token punctuation">;</span>B_u.txt\n    │   ├── kd$%K,<span class="token punctuation">)</span>24l.txt\n    │   └── piyo\n    │       ├── <span class="token punctuation">(</span><span class="token punctuation">\\</span><span class="token punctuation">\\</span>3p0ibK1S.txt\n    │       ├── B0dGSQxzmv.txt\n    │       └── ~L3<span class="token punctuation">\\</span><span class="token punctuation">\\</span>SGc<span class="token variable">$X9</span>.txt\n    ├── n<span class="token punctuation">(</span>x5@_alTr.txt\n    └── nCH:qsx<span class="token punctuation">\\</span><span class="token punctuation">\\</span><span class="token punctuation">(</span>f.txt\n\n<span class="token number">5</span> directories, <span class="token number">18</span> files\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br></div></div><p>問題なければ <code>--cold-run</code> だけを外して同じコマンドを実行してください。</p><hr><h2 id="オプション一覧" tabindex="-1"><a class="header-anchor" href="#オプション一覧" aria-hidden="true">#</a> オプション一覧</h2><table><thead><tr><th>オプション</th><th>説明</th></tr></thead><tbody><tr><td><code>-h</code>, <code>--help</code></td><td>ヘルプを表示して終了</td></tr><tr><td><code>-v</code>, <code>--version</code></td><td>バージョンを表示して終了</td></tr><tr><td><code>-n</code>, <code>--number</code></td><td>生成するファイル数（デフォルト: 1）</td></tr><tr><td><code>-e</code>, <code>--ext</code></td><td>ファイル拡張子（デフォルト: <code>txt</code>）</td></tr><tr><td><code>-s</code>, <code>--size</code></td><td>画像サイズを <code>幅x高さ</code> で指定（デフォルト: <code>100x100</code>）。画像フォーマット指定時のみ有効</td></tr><tr><td><code>-w</code>, <code>--with-whitespace</code></td><td>ファイル名に空白を含める</td></tr><tr><td><code>-z</code>, <code>--zenkaku</code></td><td>ファイル名に全角文字を含める</td></tr><tr><td><code>--no-symbol</code></td><td>ファイル名から記号を除外する</td></tr><tr><td><code>--each</code></td><td>全ての中間ディレクトリにもファイルを生成する</td></tr><tr><td><code>--cold-run</code></td><td>実際にはファイルを生成せず、プレビューのみ表示</td></tr><tr><td><code>--verbose</code></td><td>デバッグ情報を出力する</td></tr></tbody></table>',55),l={},p=(0,a(3744).Z)(l,[["render",function(n,s){return e}]])},3744:(n,s)=>{s.Z=(n,s)=>{const a=n.__vccOpts||n;for(const[n,e]of s)a[n]=e;return a}}}]);